    { id = "spiritbeast_deepseacrab_ghost-spectral", lookID = "deepseacrab_ghost-spectral", family = "spiritbeast", modelGroup = "Spirit Crabs", name = "Призрачный краб (Ghostcrawler)", nameEN = "Ghostcrawler", subTitle = "Дух краба в Бездне Вайш'ира", subTitleEN = "Spectral Crab of the Abyssal Depths", npcID = 50051, rarity = "SPIRIT", zone = "Мерцающий простор", zoneEN = "Shimmering Expanse", mapID = 205, npcIDs = {50051}, coords = {{x=19.6,y=45.4,note="Юго-западный маршрут по дну"},{x=18.2,y=78.4,note="Южная впадина"}}, npcs = {{id=50051,name="Ghostcrawler",nameEN="Ghostcrawler",level="38",tag="Рарник",tagEN="Rare",zone="Бездонные глубины",zoneEN="Abyssal Depths"}}, respawn = "4–8 часов", respawnEN = "4–8 hours", howTo = "Полупрозрачный краб-пасхалка в честь Грега Стрита (Ghostcrawler). Патрулирует по длинной дуге на западе Бездонных глубин.", howToEN = "Translucent spirit crab named after former lead systems designer Greg 'Ghostcrawler' Street. Patrols a long underwater path along the western edge of the Abyssal Depths." },
    { id = "spiritbeast_ghostlymoose", lookID = "ghostlymoose", family = "spiritbeast", modelGroup = "Spirit Elderhorns", name = "Булвинкель", nameEN = "Bulvinkel", subTitle = "Призрачный белый лось Штормхейма", subTitleEN = "Spectral White Moose of Stormheim", npcID = 111463, rarity = "SPIRIT", zone = "Штормхейм", zoneEN = "Stormheim", mapID = 634, npcIDs = {111463}, coords = {{x=80.5,y=85.4,note="Вершина горного утёса на юго-востоке"}}, npcs = {{id=111463,name="Bulvinkel",nameEN="Bulvinkel",level="10-45",tag="Рарник",tagEN="Rare",zone="Штормхейм",zoneEN="Stormheim"}}, respawn = "1–4 часа", respawnEN = "1–4 hours", howTo = "Благородный полупрозрачный лось, стоящий на самом краю высокого горного обрыва над морем на юго-востоке Штормхейма (80.5, 85.4).", howToEN = "Noble translucent moose standing at the very edge of a high coastal cliff in southeastern Stormheim (80.5, 85.4)." },
    { id = "spiritbeast_mistfoxskin-spectralightning", lookID = "mistfoxskin-spectralightning", family = "spiritbeast", modelGroup = "Spirit Foxes", name = "Громолап (Lightning Paw)", nameEN = "Lightning Paw", subTitle = "Электрический лис Сумеречного леса", subTitleEN = "Electric Spirit Fox of Duskwood", npcID = 118244, rarity = "SPIRIT", zone = "Сумеречный лес", zoneEN = "Duskwood", mapID = 47, npcIDs = {118244}, coords = {{x=20.6,y=44.2,note="Кусты на Вороньем холме"},{x=56.2,y=21.8,note="Северный лес"}}, npcs = {{id=118244,name="Lightning Paw",nameEN="Lightning Paw",level="10-60",tag="Рарник",tagEN="Rare",zone="Сумеречный лес",zoneEN="Duskwood"}}, respawn = "2–6 часов (прячется в кустах!)", respawnEN = "2–6 hours (hides inside bushes!)", howTo = "Светящийся синий лис-дух! Прячется внутри мерцающих кустов в Сумеречном лесу — слушай характерный звук электрических разрядов рядом с кустами.", howToEN = "Glowing blue Spirit Fox! Hides inside shimmering bushes across Duskwood—listen for the distinct crackling sound of electricity near the bushes." },
    { id = "spiritbeast_harkoa", lookID = "harkoa", family = "spiritbeast", modelGroup = "Spirit Leopards", name = "Локе'нахак", nameEN = "Loque'nahak", subTitle = "Спутница Хар'коа (Уникальный снежный барс)", subTitleEN = "Mate of Har'koa (Unique Spirit Leopard)", npcID = 32517, rarity = "SPIRIT", zone = "Низина Шолазар", zoneEN = "Sholazar Basin", mapID = 119, npcIDs = {32517}, coords = {{x=36.2,y=30.8,note="Северные скалы"},{x=51.0,y=81.6,note="Южная роща"},{x=71.0,y=71.4,note="Восточный склон"},{x=22.4,y=70.2,note="Юго-запад"}}, npcs = {{id=32517,name="Loque'nahak",nameEN="Loque'nahak",level="20-30",tag="Рарник",tagEN="Rare",zone="Низина Шолазар",zoneEN="Sholazar Basin"}}, respawn = "6–12 часов (7 точек спавна по кольцу Шолазар)", respawnEN = "6–12 hours (7 spawn points around Sholazar Basin)", howTo = "Самый легендарный Дух Зверя в истории WoW с уникальной моделью светящегося снежного барса. Имеет 7 фиксированных точек спавна вокруг Низины Шолазар. Совет: проверяй в Режиме Войны (War Mode ON) или на малозаселённых шардах.", howToEN = "The most iconic Spirit Beast in WoW history with a unique glowing snow leopard model. Patrols 7 fixed spawn points around Sholazar Basin. Tip: check with War Mode ON or on low-population shards." },
    { id = "spiritbeast_spectralporcupine", lookID = "spectralporcupine", family = "spiritbeast", modelGroup = "Spirit Porcupines", name = "Гуми (Gumi)", nameEN = "Gumi", subTitle = "Лазурный дикобраз-дух Вершины Кунь-Лай", subTitleEN = "Azure Spirit Porcupine of Kun-Lai Summit", npcID = 69943, rarity = "SPIRIT", zone = "Вершина Кунь-Лай", zoneEN = "Kun-Lai Summit", mapID = 379, npcIDs = {69943}, coords = {{x=54.6,y=56.2,note="Снежные склоны Кунь-Лай"}}, npcs = {{id=69943,name="Gumi",nameEN="Gumi",level="35",tag="Элита",tagEN="Elite",zone="Вершина Кунь-Лай",zoneEN="Kun-Lai Summit"}}, respawn = "30–60 минут", respawnEN = "30–60 minutes", howTo = "Синий звёздный дикобраз-дух. Опусти ХП ниже 20% для снятия иммунитета к приручению.", howToEN = "Blue starry Spirit Porcupine. Reduce its HP below 20% to remove taming immunity." },
    { id = "spiritbeast_spectralporcupinegreen", lookID = "spectralporcupinegreen", family = "spiritbeast", modelGroup = "Spirit Porcupines", name = "Хутти (Hutia)", nameEN = "Hutia", subTitle = "Нефритовый дикобраз-дух Пандарии", subTitleEN = "Jade Spirit Porcupine of the Jade Forest", npcID = 69946, rarity = "SPIRIT", zone = "Нефритовый лес", zoneEN = "The Jade Forest", mapID = 371, npcIDs = {69946}, coords = {{x=48.2,y=61.6,note="Бамбуковая роща в центре леса"}}, npcs = {{id=69946,name="Hutia",nameEN="Hutia",level="35",tag="Элита",tagEN="Elite",zone="Нефритовый лес",zoneEN="The Jade Forest"}}, respawn = "30–60 минут", respawnEN = "30–60 minutes", howTo = "Звёздный зелёный дикобраз. Чтобы он стал приручаемым, нужно аккуратно опустить его ХП ниже 20% и приручать на дистанции!", howToEN = "Starry green Spirit Porcupine. Bring its health below 20% to remove its taming immunity, then tame from range!" },
    { id = "spiritbeast_spectralporcupinered", lookID = "spectralporcupinered", family = "spiritbeast", modelGroup = "Spirit Porcupines", name = "Дегу (Degu)", nameEN = "Degu", subTitle = "Багровый дикобраз-дух Красарангских джунглей", subTitleEN = "Crimson Spirit Porcupine of Krasarang Wilds", npcID = 69947, rarity = "SPIRIT", zone = "Красарангские джунгли", zoneEN = "Krasarang Wilds", mapID = 418, npcIDs = {69947}, coords = {{x=51.2,y=77.2,note="Южное побережье Красаранга"}}, npcs = {{id=69947,name="Degu",nameEN="Degu",level="35",tag="Элита",tagEN="Elite",zone="Долина Четырех Ветров",zoneEN="Valley of the Four Winds"}}, respawn = "30–60 минут", respawnEN = "30–60 minutes", howTo = "Красный звёздный дикобраз-дух. Опусти ХП ниже 20% и держи дистанцию при приручении.", howToEN = "Red starry Spirit Porcupine. Reduce its HP below 20% and maintain distance while taming." },
    { id = "spiritbeast_spectralsaberworg", lookID = "spectralsaberworg", family = "spiritbeast", modelGroup = "Spirit Saber Worgs", name = "Сколл", nameEN = "Skoll", subTitle = "Грозовой волк Грозовой Гряды", subTitleEN = "Lightning Worg of the Storm Peaks", npcID = 35189, rarity = "SPIRIT", zone = "Грозовая гряда", zoneEN = "The Storm Peaks", mapID = 120, npcIDs = {35189}, coords = {{x=27.4,y=50.4,note="У деревни Бруннхильдар"},{x=30.2,y=64.8,note="Замерзшее озеро Бор"},{x=45.8,y=64.6,note="Подножие Храма Штормов"}}, npcs = {{id=35189,name="Skoll",nameEN="Skoll",level="30",tag="Рарник",tagEN="Rare",zone="Грозовая гряда",zoneEN="The Storm Peaks"}}, respawn = "6–10 часов (3 точки спавна)", respawnEN = "6–10 hours (3 spawn points)", howTo = "Синий наэлектризованный северный волк с дугами молний по телу. Имеет 3 точки спавна в западной части Грозовой Гряды.", howToEN = "Electric blue northern saber worg crackling with lightning arcs. Spawns at 3 locations in western Storm Peaks." },
    { id = "spiritbeast_dreamowl_fire", lookID = "dreamowl_fire", family = "spiritbeast", modelGroup = "Spirit Somnowls", name = "На'ки (Nah'qi)", nameEN = "Nah'qi", subTitle = "Огненная сова-дух Изумрудного Сна", subTitleEN = "Fiery Spirit Somnowl of the Emerald Dream", npcID = 210908, rarity = "SPIRIT", zone = "Изумрудный Сон", zoneEN = "Emerald Dream", mapID = 2200, npcIDs = {210908}, coords = {{x=54.0,y=62.0,note="Парит высоко вокруг кроны Амирдрассила"}}, npcs = {{id=210908,name="Nah'qi",nameEN="Nah'qi",level="70",tag="Элита",tagEN="Elite",zone="Изумрудный Сон",zoneEN="The Emerald Dream"}}, respawn = "1–2 часа", respawnEN = "1–2 hours", howTo = "Потрясающая огненно-духовная сова из Изумрудного Сна (модель маунта с эпохального Фиррака!). Летает высоко вокруг центрального древа.", howToEN = "Breathtaking fiery Spirit Owl in the Emerald Dream (shares the Mythic Fyrakk mount model!). Flies high around the central boughs of Amirdrassil. Requires Cinder of Companionship." },
    { id = "spiritbeast_spectraltigerblue", lookID = "spectraltigerblue", family = "spiritbeast", modelGroup = "Spirit Tigers", name = "Магрия", nameEN = "Magria", subTitle = "Лазурный призрачный тигр (Нужно снять броню!)", subTitleEN = "Azure Spectral Tiger (Unequip all armor first!)", npcID = 54319, rarity = "SPIRIT", zone = "Гора Хиджал", zoneEN = "Mount Hyjal", mapID = 198, npcIDs = {54319}, coords = {{x=29.0,y=51.4,note="Тропа через Поток Огня"}}, npcs = {{id=54319,name="Magria",nameEN="Magria",level="32-37",tag="Рарник",tagEN="Rare",zone="Гора Хиджал",zoneEN="Mount Hyjal"}}, respawn = "4–8 часов (делит спавн с Анхой)", respawnEN = "4–8 hours (shares spawn with Ankha)", howTo = "Синяя сестра Анхи. Ваншотает при наличии брони на персонаже — сними всю экипировку перед началом приручения!", howToEN = "Blue sister of Ankha. Deals lethal bonus damage based on your armor—unequip all armor pieces before taming!" },
    { id = "spiritbeast_spectraltigergreen", lookID = "spectraltigergreen", family = "spiritbeast", modelGroup = "Spirit Tigers", name = "Анха", nameEN = "Ankha", subTitle = "Белый призрачный тигр (Нужно снять броню!)", subTitleEN = "White Spectral Tiger (Unequip all armor first!)", npcID = 54318, rarity = "SPIRIT", zone = "Гора Хиджал", zoneEN = "Mount Hyjal", mapID = 198, npcIDs = {54318}, coords = {{x=29.0,y=51.4,note="Тропа через Поток Огня"},{x=40.2,y=55.4,note="Восточный край тропы"}}, npcs = {{id=54318,name="Ankha",nameEN="Ankha",level="32-37",tag="Рарник",tagEN="Rare",zone="Гора Хиджал",zoneEN="Mount Hyjal"}}, respawn = "4–8 часов (делит спавн с Магрией)", respawnEN = "4–8 hours (shares spawn with Magria)", howTo = "ВАЖНАЯ МЕХАНИКА: у Анхи способность «Металлическая ярость» — она ваншотает любого игрока в броне! Перед приручением сними ВЕСЬ шмот с показателем брони (оставь только оружие и бижутерию).", howToEN = "IMPORTANT MECHANIC: Ankha casts 'Metal Wrath', which one-shots any player wearing armor! Unequip ALL gear with an Armor value before casting Tame Beast." },
    { id = "spiritbeast_spectraltigerpurple", lookID = "spectraltigerpurple", family = "spiritbeast", modelGroup = "Spirit Tigers", name = "Гондрия", nameEN = "Gondria", subTitle = "Призрачный фиолетовый саблезуб", subTitleEN = "Spectral Purple Saber Tiger", npcID = 33776, rarity = "SPIRIT", zone = "Зул'Драк", zoneEN = "Zul'Drak", mapID = 121, npcIDs = {33776}, coords = {{x=63.0,y=63.0,note="Вокруг алтаря Мам'тот"},{x=69.6,y=48.2,note="У алтаря Кетц'лун"},{x=63.2,y=42.6,note="Северный лес"}}, npcs = {{id=33776,name="Gondria",nameEN="Gondria",level="22-32",tag="Рарник",tagEN="Rare",zone="Зул'Драк",zoneEN="Zul'Drak"}}, respawn = "6–10 часов (5 точек вокруг алтарей)", respawnEN = "6–10 hours (5 spawn points around altars)", howTo = "Полупрозрачная лилово-туманная пантера со светящимися глазами. Облетай заснеженные поляны вокруг алтарей на верхнем ярусе Зул'Драка.", howToEN = "Translucent purple-mist saber tiger with glowing eyes. Patrols snow-covered clearings around the upper-tier altars of Zul'Drak." },
    { id = "spiritbeast_stormgryphon_blue-13131", lookID = "stormgryphon_blue-13131", family = "spiritbeast", modelGroup = "Stormrooks", name = "Арадан (Aradan)", nameEN = "Aradan", subTitle = "Грозовой грифон Гнездовья (5 вариантов оперения)", subTitleEN = "Stormrook Spirit Gryphon of The Rookery (5 plumage variants)", npcID = 213428, rarity = "SPIRIT", zone = "Гнездовье", zoneEN = "The Rookery", mapID = 2315, npcIDs = {213428}, coords = {{x=58.0,y=32.0,note="Внутри подземелья Гнездовье (Дорногал)"}}, npcs = {{id=213428,name="Aradan",nameEN="Aradan",level="70-80",tag="Особый призыв",tagEN="Spawned",zone="Гнездовье",zoneEN="The Rookery"}}, respawn = "Внутри подземелья Гнездовье (100% спавн!)", respawnEN = "Inside The Rookery dungeon (100% spawn!)", howTo = "Грозовой грифон-дух из подземелья «Гнездовье» (Остров Дорн). Подбери «Грозовое перо» на берегу после 1-го босса Кириоса и используй его на Арадане!", howToEN = "Stormrook Spirit Beast inside 'The Rookery' dungeon (Isle of Dorn). Pick up the 'Void-Touched Stormfeather' on the ledge after the 1st boss Kyrioss and use it on Aradan!" },
