    { id = "spiritbeast_tigerloa", lookID = "tigerloa", family = "spiritbeast", modelGroup = "Great Spirit Tigers", name = "Сул'рака", nameEN = "Sul'raka", subTitle = "Фиолетовая теневая пантера Лоа по следам", subTitleEN = "Purple Shadow Loa Tiger (Track Heavy Footprints)", npcID = 210868, rarity = "SECRET", zone = "Изумрудный Сон", zoneEN = "Emerald Dream", mapID = 2200, npcIDs = {210868}, coords = {{x=63.0,y=67.0,note="Юго-восточный маршрут Изумрудного Сна"}}, npcs = {{id=210868,name="Sul'raka",nameEN="Sul'raka",level="70",tag="Элита",tagEN="Elite",zone="Изумрудный Сон",zoneEN="The Emerald Dream"}}, respawn = "15–30 минут (невидима без ракеты!)", respawnEN = "15–30 minutes (invisible without Flare!)", howTo = "Глубоко-фиолетовая полупрозрачная тигрица Лоа в Изумрудном Сне! Бродит в полной невидимости, оставляя на земле «Тяжелые следы». Брось перед свежим следом Осветительную ракету и Замораживающую ловушку!", howToEN = "Deep purple translucent Loa tigress in the Emerald Dream! Prowls in complete stealth while leaving 'Heavy Tracks' on the ground. Drop a Flare and Freezing Trap ahead of her fresh tracks!" },
    { id = "spiritbeast_spectralgryphon", lookID = "spectralgryphon", family = "spiritbeast", modelGroup = "Spectral Gryphons", name = "Затерянный спектральный грифон", nameEN = "Lost Spectral Gryphon", subTitle = "Призрачный грифон Штормграда (Клик по перу)", subTitleEN = "Ghostly Gryphon of Stormwind (Click Spectral Feather)", npcID = 121567, rarity = "SECRET", zone = "Штормград", zoneEN = "Stormwind City", mapID = 84, npcIDs = {121567}, coords = {{x=71.2,y=72.5,note="Пёрышко прямо у распорядителя полётов Штормграда!"}}, npcs = {{id=121567,name="Lost Spectral Gryphon",nameEN="Lost Spectral Gryphon",level="10-60",zone="Штормград",zoneEN="Stormwind City"}}, respawn = "15–45 минут (клик по Призрачному перу)", respawnEN = "15–45 minutes (click Spectral Feather)", howTo = "Прилети к мастеру полётов Штормграда (71.2, 72.5) — даже за Орду под Черепахой/Камуфляжем! Прямо на сене у гнезда лежит «Призрачное перо». Кликни по нему — грифон мгновенно материализуется перед тобой!", howToEN = "Fly to the Stormwind Flight Master (71.2, 72.5)—even as Horde using Aspect of the Turtle / Camouflage! Click the 'Spectral Feather' on the hay by the nest to summon the gryphon on the spot!" },
    { id = "spiritbeast_raptor2_lightning-frost", lookID = "raptor2_lightning-frost", family = "spiritbeast", modelGroup = "Spirit Raptors", name = "Гон", nameEN = "Gon", subTitle = "Призрачный ящер Оргриммара (Клик по скорлупе)", subTitleEN = "Spectral Raptor of Orgrimmar (Click Spectral Eggshell)", npcID = 121571, rarity = "SECRET", zone = "Оргриммар", zoneEN = "Orgrimmar", mapID = 85, npcIDs = {121571}, coords = {{x=35.6,y=69.0,note="Призрачная скорлупа у костра в хижине"}}, npcs = {{id=121571,name="Gon",nameEN="Gon",level="10-60",tag="Особый призыв",tagEN="Spawned",zone="Оргриммар",zoneEN="Orgrimmar"}}, respawn = "15–45 минут (клик по Призрачной скорлупе)", respawnEN = "15–45 minutes (click Spectral Eggshell)", howTo = "Зайди в большую шаманскую хижину на Аллее Духов Оргриммара (35.6, 69.0). У черепов справа на полу лежит маленькая «Спектральная яичная скорлупа». Нажми на неё — появится Гон!", howToEN = "Enter the large shaman hut in Orgrimmar's Valley of Spirits (35.6, 69.0). Click the small 'Spectral Eggshell' on the floor next to the skulls to summon Gon!" },
    { id = "spiritbeast_wolfdraenor_shadow", lookID = "wolfdraenor_shadow", family = "spiritbeast", modelGroup = "Spirit Wolves", name = "Гара", nameEN = "Gara", subTitle = "Волчица Бездны (Секретная цепочка ритуала)", subTitleEN = "Void Wolf Spirit Beast (Secret Ritual Questline)", npcID = 88708, rarity = "SECRET", zone = "Долина Призрачной Луны", zoneEN = "Shadowmoon Valley", mapID = 539, npcIDs = {88708,88710}, coords = {{x=28.6,y=35.8,note="Погост у кургана (Старт цепочки)"},{x=56.8,y=21.6,note="Древо столпов для ритуала"}}, npcs = {{id=88708,name="Gara",nameEN="Gara",level="10-40",zone="Долина Призрачной Луны",zoneEN="Shadowmoon Valley"},{id=88710,name="Lost Netherwolf",nameEN="Lost Netherwolf",level="10-40",zone="Долина Призрачной Луны",zoneEN="Shadowmoon Valley"}}, respawn = "Мгновенно по завершении личного ритуала (100% гарантия!)", respawnEN = "Instant upon completing personal ritual (100% guaranteed!)", howTo = "Секретный фиолетовый Дух Зверя без конкуренции с другими хантами! Шаг 1: Почеши Гару на погосте (28.6, 35.8) и покажи ей Сумеречную ягоду. Шаг 2: Собери 6 предметов по Дренору для Чучела. Шаг 3: Уложи чучело у могилы Гары, возьми Теневой фонарь с владыки Бездны и войди в мир Бездны у Древа (56.8, 21.6).", howToEN = "Secret purple Spirit Beast with zero competition! Step 1: Scratch Gara's ears at the burial mound (28.6, 35.8) and show her Shadowberries. Step 2: Gather 6 items across Draenor to build an Effigy. Step 3: Place the Effigy at Gara's grave, loot the Shadow Lantern in Pillars of Fate, and enter the Void phase at the Great Tree (56.8, 21.6)." },
    { id = "spiritbeast_celestialserpent", lookID = "celestialserpent", family = "spiritbeast", modelGroup = "Astral Cloud Serpents", name = "Элегон", nameEN = "Elegon", subTitle = "Звёздный астральный облачный змей", subTitleEN = "Celestial Astral Cloud Serpent", npcID = 60410, rarity = "BOSS", zone = "Вершина Кунь-Лай", zoneEN = "Kun-Lai Summit", mapID = 379, npcIDs = {60410}, coords = {{x=59.6,y=39.2,note="Вход в рейд Подземелья Могу'шан"}}, npcs = {{id=60410,name="Elegon",nameEN="Elegon",level="Boss",tag="Босс",tagEN="Boss",zone="Подземелья Могу'шан",zoneEN="Mogu'shan Vaults"}}, respawn = "Внутри рейда на любой сложности (100% спавн!)", respawnEN = "Inside Mogu'shan Vaults raid on any difficulty (100% guaranteed!)", howTo = "Звёздный дракон Элегон приручается как Дух Зверя (не требует книги облачных змеев, только спек БМ)! Зайди в рейд Подземелья Могу'шан, дойди до 5-го босса и приручи.", howToEN = "Celestial dragon Elegon is classified as a Spirit Beast (does NOT require the Cloud Serpent tome, only Beast Mastery spec)! Enter Mogu'shan Vaults, reach the 5th boss, and tame." },
